    ImmutableEventLog(java.util.List<String> zdarzenia) {
        this.zdarzenia = java.util.List.copyOf(zdarzenia);
    }
    java.util.List<String> wszystkie() {
        return java.util.List.copyOf(zdarzenia); // druga kopia, choc niepotrzebna
    }
}
// Skoro konstruktor JUZ zapisal trwale niemodyfikowalna liste (List.copyOf w konstruktorze),
// ponowne kopiowanie w getterze jest NIEPOTRZEBNYM narzutem wydajnosciowym - wystarczy
// zwrocic ta sama referencje (jak w FixedImmutablePerson.getHobbies() z teorii). Kopiowanie
// przy KAZDYM wywolaniu gettera ma sens TYLKO, jesli pole samo MOZE byc mutowalne
// (np. gdy uzywamy zwyklej ArrayList wewnatrz zamiast List.copyOf).

