static <T> java.util.List<T> widokLubKopia(java.util.List<T> input, boolean uzyjKopii) {
    return uzyjKopii ? java.util.List.copyOf(input) : java.util.Collections.unmodifiableList(input);
}

java.util.List<String> input = new java.util.ArrayList<>(java.util.List.of("A"));
var widok = widokLubKopia(input, false);
var kopia = widokLubKopia(input, true);
input.add("B");
System.out.println("widok: " + widok); // [A, B]
System.out.println("kopia: " + kopia); // [A]

java.util.List<Integer> duza = new java.util.ArrayList<>();
for (int i = 0; i < 100_000; i++) duza.add(i);

long t1 = System.nanoTime();
java.util.Collections.unmodifiableList(duza);
long unmodTime = System.nanoTime() - t1;

long t2 = System.nanoTime();
java.util.List.copyOf(duza);
long copyTime = System.nanoTime() - t2;

System.out.println("unmodifiableList: " + unmodTime + " ns");
System.out.println("List.copyOf: " + copyTime + " ns");
// Wniosek: unmodifiableList jest praktycznie natychmiastowy (O(1), tylko tworzy wrapper),
// List.copyOf jest zauwazalnie wolniejszy dla duzych list (O(n), kopiuje CALA zawartosc) -
// swiadomy kompromis miedzy wydajnoscia (widok) a pelnym bezpieczenstwem (kopia).

class ImmutableGraph {
    private final java.util.Map<String, java.util.Set<String>> sasiedzi;
    ImmutableGraph(java.util.Map<String, java.util.Set<String>> sasiedzi) {
        java.util.Map<String, java.util.Set<String>> kopia = new java.util.HashMap<>();
        for (var entry : sasiedzi.entrySet()) {
            kopia.put(entry.getKey(), java.util.Set.copyOf(entry.getValue())); // kopia KAZDEGO Set
        }
        this.sasiedzi = java.util.Map.copyOf(kopia); // kopia samej mapy
    }
    java.util.Map<String, java.util.Set<String>> getSasiedzi() { return sasiedzi; }
}

java.util.Map<String, java.util.Set<String>> dane = new java.util.HashMap<>();
java.util.Set<String> sasiedziA = new java.util.HashSet<>(java.util.Set.of("B"));
dane.put("A", sasiedziA);
ImmutableGraph graph = new ImmutableGraph(dane);
sasiedziA.add("C"); // mutacja oryginalnego Set - NIE wplywa na graph, bo Set tez zostal skopiowany
System.out.println(graph.getSasiedzi());

// KOMPLETNY CHECKLIST bezpiecznej, niemutowalnej klasy:
// 1. Wszystkie pola sa 'private final'.
// 2. Klasa jest oznaczona jako 'final' (blokuje mutowalne podklasy).
// 3. Brak jakichkolwiek setterow czy innych metod mutujacych pola.
// 4. Wartosci pol przypisywane WYLACZNIE w konstruktorze, z walidacja inwariantow.
// 5. Dla kazdego pola typu mutowalnego (List/Map/Set/tablica/klasa z setterami) -
//    DEFENSYWNA KOPIA na WEJSCIU, w konstruktorze (List.copyOf/Map.copyOf/clone()).
// 6. Getter dla pola typu mutowalnego zwraca albo JUZ trwale niemodyfikowalna referencje
//    (jesli konstruktor uzyl copyOf), albo DODATKOWA kopie (jesli pole jest mutowalne
//    WEWNATRZ klasy).
// 7. Swiadomosc PLYTKIEJ vs GLEBOKIEJ kopii - jesli ELEMENTY kolekcji same sa mutowalne,
//    plytka kopia (List.copyOf) NIE WYSTARCZA, trzeba sklonowac kazdy element osobno.

class ImmutableSchedule {
    private final java.util.List<java.time.LocalDateTime> terminy;
    ImmutableSchedule(java.util.List<java.time.LocalDateTime> terminy) {
        this.terminy = java.util.List.copyOf(terminy);
    }
    java.util.List<java.time.LocalDateTime> getTerminy() { return terminy; }
}
// Plytka kopia (List.copyOf) w PELNI wystarcza, bo java.time.LocalDateTime jest CALKOWICIE
// niemutowalny (patrz Lesson07_DateAndTime w _01_fundamentals) - nie istnieje ZADNA metoda
// mutujaca stan istniejacego LocalDateTime (kazda 'zmiana' jak plusDays() zwraca NOWY obiekt).
// Dlatego nie ma ryzyka, ze ktos zmieni ELEMENT listy przez zewnetrzna referencje - elementy
// same z siebie sa juz bezpieczne, wiec gleboka kopia bylaby zbednym narzutem.

class ImmutableDocument {
    private final byte[] zawartosc;
    ImmutableDocument(byte[] zawartosc) { this.zawartosc = zawartosc.clone(); }
    byte[] getZawartosc() { return zawartosc.clone(); }
}

ImmutableDocument doc = new ImmutableDocument(new byte[]{1, 2, 3});
byte[] odbiorca1 = doc.getZawartosc();
byte[] odbiorca2 = doc.getZawartosc();
odbiorca1[0] = 99;
System.out.println(java.util.Arrays.toString(odbiorca1)); // [99, 2, 3]
System.out.println(java.util.Arrays.toString(odbiorca2)); // [1, 2, 3] - bez zmian
System.out.println(java.util.Arrays.toString(doc.getZawartosc())); // [1, 2, 3] - oryginal bez zmian

class ImmutableWrapper<T> {
    private final T value;
    ImmutableWrapper(T value, java.util.function.UnaryOperator<T> kopiujacy) {
        this.value = kopiujacy.apply(value);
    }
    T getValue() { return value; }
}

ImmutableWrapper<java.util.List<String>> w1 = new ImmutableWrapper<>(
    new java.util.ArrayList<>(java.util.List.of("a")), java.util.List::copyOf);
System.out.println(w1.getValue());

class Punkt { int x; Punkt(int x) { this.x = x; } Punkt kopia() { return new Punkt(x); } }
ImmutableWrapper<Punkt> w2 = new ImmutableWrapper<>(new Punkt(5), Punkt::kopia);
System.out.println(w2.getValue().x);

/**
 * UWAGA: ta metoda NIE kopiuje przekazanej listy - przejmuje jej WLASNOSC (ownership).
 * Wywolujacy NIE MOZE juz modyfikowac 'list' po przekazaniu jej tutaj.
 */
static <T> java.util.List<T> unsafeWrap(java.util.List<T> list) {
    return java.util.Collections.unmodifiableList(list);
}
// Taki kompromis (brak kopii, tylko kontrakt w dokumentacji) bywa akceptowalny w REALNYCH
// bibliotekach, gdy wydajnosc jest krytyczna, a autor API ma pewnosc/kontrole, ze wywolujacy
// PRZESTRZEGA kontraktu (np. wewnetrzne API w tym samym module, gdzie autor kontroluje OBIE
// strony). Sam List.of(...) w JDK w praktyce ROBI kopie (lub uzywa niemodyfikowalnych
// wewnetrznych struktur) dla bezpieczenstwa publicznego API - 'unsafeWrap' jest wzorem tego,
// czego NALEZY unikac w publicznym, ogolnodostepnym kodzie bibliotecznym.

java.util.List<String> pierwsza = java.util.List.copyOf(java.util.List.of("a", "b"));
java.util.List<String> druga = java.util.List.copyOf(pierwsza);
System.out.println(pierwsza == druga); // true - optymalizacja, brak zbednego kopiowania

class ImmutableConfig2 {
    private final java.util.Map<String, String> ustawienia;
    ImmutableConfig2(java.util.Map<String, String> u) { this.ustawienia = java.util.Map.copyOf(u); }
    java.util.Map<String, String> getUstawienia() { return ustawienia; }
}

ImmutableConfig2 config = new ImmutableConfig2(java.util.Map.of("tryb", "prod"));
java.util.concurrent.atomic.AtomicInteger licznikWyjatkow = new java.util.concurrent.atomic.AtomicInteger();

Runnable reader = () -> System.out.println(Thread.currentThread().getName() + ": " + config.getUstawienia());
Runnable writer = () -> {
    try { config.getUstawienia().put("x", "y"); }
    catch (UnsupportedOperationException e) { licznikWyjatkow.incrementAndGet(); }
};
Thread t1 = new Thread(reader), t2 = new Thread(reader), t3 = new Thread(writer);
t1.start(); t2.start(); t3.start();
try { t1.join(); t2.join(); t3.join(); } catch (InterruptedException e) {}
System.out.println("Zlapane wyjatki: " + licznikWyjatkow.get());

class ImmutableMatrix {
    private final int[][] dane;
    ImmutableMatrix(int[][] dane) {
        this.dane = new int[dane.length][];
        for (int i = 0; i < dane.length; i++) {
            this.dane[i] = dane[i].clone(); // klonuj KAZDY wiersz osobno
        }
    }
    int[][] getDane() {
        int[][] kopia = new int[dane.length][];
        for (int i = 0; i < dane.length; i++) kopia[i] = dane[i].clone();
        return kopia;
    }
}

int[][] oryginal = {{1, 2}, {3, 4}};
ImmutableMatrix matrix = new ImmutableMatrix(oryginal);
oryginal[0][0] = 999;
System.out.println(java.util.Arrays.deepToString(matrix.getDane())); // [[1, 2], [3, 4]] - bez zmian

class Strategie {
    private final java.util.List<String> dane = new java.util.ArrayList<>(java.util.List.of("a", "b"));
    java.util.List<String> zywaReferencja() { return dane; } // (a) niebezpieczne
    java.util.List<String> widok() { return java.util.Collections.unmodifiableList(dane); } // (b)
    java.util.List<String> kopia() { return java.util.List.copyOf(dane); } // (c)
}

Strategie s = new Strategie();
s.zywaReferencja().add("HACK"); // (a) DZIALA - zmienia stan wewnetrzny, brak ochrony!
System.out.println(s.widok()); // pokazuje HACK - widok NIE chronil, bo zmiana byla przez (a)
try { s.widok().add("x"); } catch (UnsupportedOperationException e) { System.out.println("(b) blokuje mutacje PRZEZ SIEBIE"); }
try { s.kopia().add("y"); } catch (UnsupportedOperationException e) { System.out.println("(c) blokuje mutacje PRZEZ SIEBIE"); }
// (a) nie chroni NICZEGO - pelny dostep do stanu wewnetrznego.
// (b) chroni przed mutacja PRZEZ SAM WIDOK, ale nie przed mutacja oryginalu skads indziej.
// (c) chroni w PELNI - kopia jest calkowicie niezalezna od oryginalu.

final class ImmutableCache<K, V> {
    private final java.util.Map<K, V> dane;
    ImmutableCache(java.util.Map<K, V> dane) { this.dane = java.util.Map.copyOf(dane); }
    V get(K key) { return dane.get(key); }
}

ImmutableCache<String, Integer> cache = new ImmutableCache<>(java.util.Map.of("a", 1, "b", 2));
// Wiele watkow moze wywolywac cache.get(...) rownolegle BEZ synchronized/ConcurrentHashMap,
// bo mapa WEWNATRZ nigdy sie nie zmienia po konstruktorze - nie ma zadnej sytuacji 'watek A
// pisze, watek B czyta w polowie zmiany', bo PISANIE po konstruktorze jest fizycznie
// niemozliwe (Map.copyOf zwraca trwale niemodyfikowalna mape). To dokladnie ta sama zasada
// co w Lesson10_ThreadSafety (_05_multithreading): brak mozliwosci mutacji eliminuje
// wszystkie klasyczne problemy watkowe u zrodla.

final class OrderSnapshot {
    private final String orderId;
    private final String klient;
    private final java.util.List<String> pozycje;
    private final java.math.BigDecimal suma;

    OrderSnapshot(String orderId, String klient, java.util.List<String> pozycje, java.math.BigDecimal suma) {
        if (orderId == null || klient == null) throw new IllegalArgumentException("orderId/klient nie moga byc null");
        this.orderId = orderId;
        this.klient = klient;
        this.pozycje = java.util.List.copyOf(pozycje);
        this.suma = suma;
    }

    java.util.List<String> getPozycje() { return pozycje; }
    java.math.BigDecimal getSuma() { return suma; }
}

var oryginalneOnPozycje = new java.util.ArrayList<>(java.util.List.of("Laptop"));
var snapshot = new OrderSnapshot("O-1", "Ala", oryginalneOnPozycje, new java.math.BigDecimal("3500"));

oryginalneOnPozycje.add("Mysz"); // proba 1: mutacja oryginalu
var czyProba1Zawiodla = !snapshot.getPozycje().contains("Mysz");

try {
    snapshot.getPozycje().add("Klawiatura"); // proba 2: mutacja przez getter
} catch (UnsupportedOperationException e) {
    System.out.println("Proba 2 zawiodla jak trzeba: " + e.getClass().getSimpleName());
}

System.out.println("Proba 1 zawiodla: " + czyProba1Zawiodla);
